class Solution:
    def maxProduct(self, s: str) -> int:
        n = len(s)

        def pal(t):
            return t == t[::-1]

        best = 0
        def dfs(i, a, b):
            nonlocal best
            if i == n:
                if a and b and pal(a) and pal(b):
                    best = max(best, len(a) * len(b))
                return
            dfs(i + 1, a + s[i], b)
            dfs(i + 1, a, b + s[i])
            dfs(i + 1, a, b)

        dfs(0, "", "")
        return best

