class Solution {
public:
    int maxProduct(string s) {
        int n = s.size(), best = 0;
        function<void(int, string, string)> dfs = [&](int i, string a, string b) {
            if (i == n) {
                if (!a.empty() && !b.empty()) {
                    string ra(a.rbegin(), a.rend()), rb(b.rbegin(), b.rend());
                    if (a == ra && b == rb)
                        best = max(best, (int)a.size() * (int)b.size());
                }
                return;
            }
            dfs(i + 1, a + s[i], b);
            dfs(i + 1, a, b + s[i]);
            dfs(i + 1, a, b);
        };
        dfs(0, "", "");
        return best;
    }
};

