class Solution {
    private int best = 0;
    private String s;

    public int maxProduct(String s) {
        this.s = s;
        dfs(0, new StringBuilder(), new StringBuilder());
        return best;
    }

    private void dfs(int i, StringBuilder a, StringBuilder b) {
        if (i == s.length()) {
            if (a.length() > 0 && b.length() > 0 && isPal(a) && isPal(b))
                best = Math.max(best, a.length() * b.length());
            return;
        }
        a.append(s.charAt(i));
        dfs(i + 1, a, b);
        a.deleteCharAt(a.length() - 1);
        b.append(s.charAt(i));
        dfs(i + 1, a, b);
        b.deleteCharAt(b.length() - 1);
        dfs(i + 1, a, b);
    }

    private boolean isPal(StringBuilder t) {
        int l = 0, r = t.length() - 1;
        while (l < r)
            if (t.charAt(l++) != t.charAt(r--)) return false;
        return true;
    }
}

