class Solution:
    def maxProduct(self, s: str) -> int:
        n = len(s)
        full = (1 << n) - 1
        length = [0] * (full + 1)
        is_pal = [False] * (full + 1)
        for m in range(full + 1):
            chars = [s[i] for i in range(n) if m >> i & 1]
            length[m] = len(chars)
            is_pal[m] = chars == chars[::-1]
        best = 0
        for a in range(1, full + 1):
            if not is_pal[a]:
                continue
            rest = full ^ a
            b = rest
            while b:
                if is_pal[b]:
                    best = max(best, length[a] * length[b])
                b = (b - 1) & rest
        return best

