class Solution {
public:
    int maxProduct(string s) {
        int n = s.size(), full = (1 << n) - 1;
        vector<int> len(full + 1, 0);
        vector<char> pal(full + 1, false);
        for (int m = 0; m <= full; m++) {
            string t;
            for (int i = 0; i < n; i++)
                if ((m >> i) & 1) t += s[i];
            len[m] = t.size();
            pal[m] = equal(t.begin(), t.end(), t.rbegin());
        }
        int best = 0;
        for (int a = 1; a <= full; a++) {
            if (!pal[a]) continue;
            int rest = full ^ a;
            for (int b = rest; b > 0; b = (b - 1) & rest)
                if (pal[b]) best = max(best, len[a] * len[b]);
        }
        return best;
    }
};

