class Solution {
    public int maxProduct(String s) {
        int n = s.length(), full = (1 << n) - 1;
        int[] len = new int[full + 1];
        boolean[] pal = new boolean[full + 1];
        for (int m = 0; m <= full; m++) {
            StringBuilder t = new StringBuilder();
            for (int i = 0; i < n; i++)
                if (((m >> i) & 1) == 1) t.append(s.charAt(i));
            len[m] = t.length();
            pal[m] = isPal(t.toString());
        }
        int best = 0;
        for (int a = 1; a <= full; a++) {
            if (!pal[a]) continue;
            int rest = full ^ a;
            for (int b = rest; b > 0; b = (b - 1) & rest)
                if (pal[b]) best = Math.max(best, len[a] * len[b]);
        }
        return best;
    }

    private boolean isPal(String t) {
        int l = 0, r = t.length() - 1;
        while (l < r)
            if (t.charAt(l++) != t.charAt(r--)) return false;
        return true;
    }
}

